# Verify that timezone_name returns the database TIME_ZONE setting

import django
from django.conf import settings

settings.configure(
    DEBUG=True,
    DATABASES={
        'default': {
            'ENGINE': 'django.db.backends.mysql',
            'TIME_ZONE': 'Europe/Paris',  # Set database timezone
        }
    },
    USE_TZ=True,
    TIME_ZONE='America/New_York',  # Different Django timezone
)

# Create a mock connection settings dict
settings_dict = {'TIME_ZONE': 'Europe/Paris'}

# Simulate the timezone_name property
def get_timezone_name(settings_dict):
    if not settings.USE_TZ:
        return settings.TIME_ZONE
    elif settings_dict['TIME_ZONE'] is None:
        return 'UTC'
    else:
        return settings_dict['TIME_ZONE']

result = get_timezone_name(settings_dict)
print(f'Timezone name for database with TIME_ZONE=Europe/Paris: {result}')
assert result == 'Europe/Paris'

# Test default case
settings_dict = {'TIME_ZONE': None}
result = get_timezone_name(settings_dict)
print(f'Timezone name for database with TIME_ZONE=None: {result}')
assert result == 'UTC'

print('All verifications passed!')
"

